import React, { useState, useEffect } from "react";
import ComplaintForm from "./components/ComplaintForm";
import ComplaintList from "./components/ComplaintList";

function App() {
  const [complaints, setComplaints] = useState([]);

  useEffect(() => {
    fetch("http://localhost:8080/complaints")
      .then((res) => res.json())
      .then((data) => setComplaints(data))
      .catch((err) => console.error(err));
  }, []);

  const handleComplaintSubmit = (complaint) => {
    fetch("http://localhost:8080/complaints", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(complaint),
    })
      .then((res) => res.json())
      .then((newComplaint) => setComplaints([...complaints, newComplaint]))
      .catch((err) => console.error(err));
  };

  return (
    <div>
      <h1>Smart Complaint Management Portal</h1>
      <ComplaintForm onComplaintSubmit={handleComplaintSubmit} />
      <ComplaintList complaints={complaints} />
    </div>
  );
}

export default App;
